CREATE VIEW business_entities AS SELECT * FROM (SELECT tenant_id,'uruns' AS kind,id,data FROM urun UNION ALL SELECT tenant_id,'ureticis' AS kind,id,data FROM uretici UNION ALL SELECT tenant_id,'kdv-kategorisis' AS kind,id,data FROM kdv_kategorisi UNION ALL SELECT tenant_id,'urun-fiyats' AS kind,id,data FROM urun_fiyat) UNION ALL SELECT * FROM (SELECT tenant_id,'urun-fiyat-hesaps' AS kind,id,data FROM urun_fiyat_hesap UNION ALL SELECT tenant_id,'kisilers' AS kind,id,data FROM kisiler UNION ALL SELECT tenant_id,'satis' AS kind,id,data FROM satis UNION ALL SELECT tenant_id,'satis-stok-hareketleris' AS kind,id,data FROM satis_stok_hareketleri) UNION ALL SELECT * FROM (SELECT tenant_id,'stok-girisis' AS kind,id,data FROM stok_girisi UNION ALL SELECT tenant_id,'giders' AS kind,id,data FROM gider UNION ALL SELECT tenant_id,'virmen' AS kind,id,data FROM virman UNION ALL SELECT tenant_id,'borc-alacaks' AS kind,id,data FROM borc_alacak) UNION ALL SELECT * FROM (SELECT tenant_id,'kasa-hareketleris' AS kind,id,data FROM kasa_hareketleri UNION ALL SELECT tenant_id,'nobet-hareketleris' AS kind,id,data FROM nobet_hareketleri UNION ALL SELECT tenant_id,'uretici-odemeleris' AS kind,id,data FROM uretici_odemeleri UNION ALL SELECT tenant_id,'nobet-duzeltmeler' AS kind,id,data FROM nobet_duzeltmeler);
CREATE TABLE business_tenant_meta(tenant_id INTEGER NOT NULL REFERENCES tenants(id),key TEXT NOT NULL,value TEXT,PRIMARY KEY(tenant_id,key));
CREATE TABLE business_sequences(tenant_id INTEGER NOT NULL REFERENCES tenants(id),kind TEXT NOT NULL,value INTEGER,PRIMARY KEY(tenant_id,kind));
CREATE TABLE business_users_snapshot(tenant_id INTEGER NOT NULL REFERENCES tenants(id),id INTEGER NOT NULL,data TEXT,PRIMARY KEY(tenant_id,id));
CREATE TABLE business_history(tenant_id INTEGER NOT NULL REFERENCES tenants(id),id INTEGER NOT NULL,kind TEXT,entity_id INTEGER,actor TEXT,operation TEXT,before_json TEXT,after_json TEXT,at TEXT,PRIMARY KEY(tenant_id,id));
CREATE TABLE business_outbox(tenant_id INTEGER NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,payload TEXT,created_at TEXT,delivered_at TEXT,queued_at TEXT,PRIMARY KEY(tenant_id,id));
CREATE TABLE business_idempotency(tenant_id INTEGER NOT NULL REFERENCES tenants(id),key TEXT NOT NULL,fingerprint TEXT,response TEXT,created_at TEXT,PRIMARY KEY(tenant_id,key));
CREATE TABLE business_backup_runs(tenant_id INTEGER NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,created_at TEXT,metadata TEXT,PRIMARY KEY(tenant_id,id));
CREATE TABLE business_backup_records(tenant_id INTEGER NOT NULL REFERENCES tenants(id),run_id TEXT NOT NULL,section TEXT NOT NULL,ordinal INTEGER NOT NULL,data TEXT,PRIMARY KEY(tenant_id,run_id,section,ordinal));
CREATE INDEX business_history_entity ON business_history(tenant_id,kind,entity_id,id);
CREATE INDEX business_outbox_pending ON business_outbox(tenant_id,delivered_at,queued_at,created_at);
CREATE TABLE report_files(tenant_id INTEGER NOT NULL REFERENCES tenants(id),key TEXT NOT NULL,uploaded TEXT NOT NULL,size INTEGER NOT NULL CHECK(size>=0),metadata TEXT NOT NULL CHECK(json_valid(metadata)),content_type TEXT NOT NULL,PRIMARY KEY(tenant_id,key));
CREATE TABLE report_file_chunks(tenant_id INTEGER NOT NULL,key TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0),data BLOB NOT NULL,PRIMARY KEY(tenant_id,key,ordinal),FOREIGN KEY(tenant_id,key) REFERENCES report_files(tenant_id,key) ON DELETE CASCADE);
